25	// Built-in functional engine ids (the qemu64/qemu32 pair). Declared once here so
26	// builtin_qemu_arch, the hybrid plan steps, and `run --mode fast` acceptance all
27	// agree -- a renamed literal would otherwise break find_engine() lookups only at
28	// run time.
29	inline constexpr const char* kQemuId64 = "qemu64";
30	inline constexpr const char* kQemuId32 = "qemu32";
31	
32	struct Discovery {
33	  std::vector<EngineDescriptor> engines;   // deduped by id; qemu first
34	  std::vector<std::string> warnings;       // binaries that failed to describe
35	};
36	
37	Discovery discover_engines();
38	
39	// Directory discover_engines() scans for sim_* engines when $ANDESIM_ENGINES_DIR
40	// is unset: VSIM_BIN_DIR (the external prebuilt vsim build, mirroring
41	// QEMU_BIN_DIR) resolved env-first then from config.env, else the legacy in-tree
42	// <repo>/verilator/build.
43	std::filesystem::path vsim_scan_dir();
44	
45	// The bundled qemu descriptor (no directory scan, no --describe subprocess).
46	// discover_engines() seeds the registry with it; `run --mode fast` resolves
47	// qemu through it directly, paying none of the Verilator-engine discovery cost.
48	// builtin_qemu_arch(xlen) builds the rv64 "qemu64" (xlen=64) or rv32 "qemu32"
49	// (xlen=32, qemu-system-riscv32); builtin_qemu() is the rv64 default.
50	EngineDescriptor builtin_qemu_arch(int xlen);
51	EngineDescriptor builtin_qemu();
52	
53	// Rewrite a discovered engine's identity from the third-party simulator name to
54	// the product name: type "verilator" -> "vsim", id "verilator:<cfg>" ->
55	// "vsim:<cfg>". discover_engines() applies this once, before the id is used for
56	// dedup or shown anywhere, so every downstream consumer (list / --engine /
57	// errors / run banner) speaks "vsim" and a user never sees "verilator". Any
58	// other backend (qemu, a drop-in alioth/sid) passes through untouched.
59	inline void normalize_engine_label(EngineDescriptor& d) {
60	  if (d.type == "verilator") d.type = "vsim";
61	  if (d.id.rfind("verilator:", 0) == 0) d.id = "vsim:" + d.id.substr(10);
62	  // The CLI exposes the marker delimiter as `--trigger marker`; some engines
63	  // report it under their internal name "csr" via --describe. Speak the CLI's
64	  // vocabulary in list / doctor too, like verilator -> vsim above.
65	  for (std::string& t : d.triggers)
66	    if (t == "csr") t = "marker";
67	}
68	
69	// Select the cycle-accurate engine for `run --mode cycle` from an
70	// already-discovered set (pure; spawns nothing). With `want_id` empty, default
71	// to the sole cycle-accurate engine -- erroring if there are none or more than
72	// one (ambiguous). With `want_id` set, that engine must exist and be
73	// cycle-accurate. Returns nullptr and sets `err` (naming the available
74	// cycle-accurate ids) on any failure; the returned pointer aliases into
75	// `engines`, so it must outlive the result.
76	inline const EngineDescriptor* resolve_accurate_engine(
77	    const std::vector<EngineDescriptor>& engines, const std::string& want_id,
78	    std::string& err) {
79	  auto is_accurate = [](const EngineDescriptor& e) {
80	    return e.kind == "cycle-accurate";
81	  };
82	  auto accurate_ids = [&] {
83	    std::vector<std::string> ids;
84	    for (const EngineDescriptor& e : engines)
85	      if (is_accurate(e)) ids.push_back(e.id);
86	    return join(ids, ", ");
87	  };
88	
89	  if (!want_id.empty()) {  // explicit --engine
90	    for (const EngineDescriptor& e : engines) {
91	      if (e.id != want_id) continue;
92	      if (is_accurate(e)) return &e;
93	      err = "engine '" + want_id + "' is " +
94	            (e.kind.empty() ? "not cycle-accurate" : e.kind) +
95	            "; a cycle-accurate engine is required";
96	      return nullptr;
97	    }
98	    std::string have = accurate_ids();
99	    err = "no engine '" + want_id + "'" +
100	          (have.empty() ? " (no cycle-accurate engines found)"
101	                        : " (cycle-accurate engines: " + have + ")");
102	    return nullptr;
103	  }
104	
105	  // No --engine: default to the sole cycle-accurate engine.
106	  const EngineDescriptor* sole = nullptr;
107	  int n = 0;
108	  for (const EngineDescriptor& e : engines)
109	    if (is_accurate(e)) { sole = &e; ++n; }
110	  if (n == 1) return sole;
111	  if (n == 0)
112	    err = "model cycle: no cycle-accurate engine found "
113	          "(build one with: scripts/build_all.sh vsim)";
114	  else
115	    err = "model cycle: multiple cycle-accurate engines; select one with "
116	          "--engine (have: " + accurate_ids() + ")";
117	  return nullptr;
118	}
