103	
104	// A major command line at column 0: `name   brief`.
105	void print_major(std::FILE* out, const char* name, const char* brief) {
106	  std::fprintf(out, "%-7s %s\n", name, brief);
107	}
108	
109	// A subcommand/target line, indented two under its command: `  name   brief`.
110	void print_sub(std::FILE* out, const char* name, const char* brief) {
111	  std::fprintf(out, "  %-9s %s\n", name, brief);
112	}
113	
114	// An option line: `<indent>--flag    [TAG  ]brief`, flags aligned to a column.
115	void print_opt(std::FILE* out, const OptRow& o) {
116	  if (o.tag[0])
117	    std::fprintf(out, "%-29s %s  %s\n", o.flag, o.tag, o.brief);
118	  else
119	    std::fprintf(out, "%-29s %s\n", o.flag, o.brief);
120	}
121	
122	// `run`: major line, the mode subcommands, then the option list (dev options
123	// only under ANDESIM_DEV). Shared by the top-level tree and `run --help`.
124	void print_run_block(std::FILE* out) {
125	  print_major(out, "run", "run one simulation");
126	  for (const ModeRow& m : kRunModes) print_sub(out, m.name, m.brief);
127	  std::fputs("\n", out);
128	  for (const OptRow& o : kRunOpts) {
129	    if (o.dev && !is_dev_mode()) continue;
130	    print_opt(out, o);
131	  }
132	}
133	
134	void print_list_block(std::FILE* out) {
135	  print_major(out, "list", "list what is available");
136	  for (const TargetRow& t : kListTargets) {
137	    if (t.dev && !is_dev_mode()) continue;
138	    print_sub(out, t.name, t.brief);
139	  }
140	}
141	
142	void print_doctor_block(std::FILE* out) {
143	  print_major(out, "doctor", "check toolchain + fixtures are present");
144	}
145	
146	// Top-level `andesim --help`: the whole tree -- every major command, its
147	// subcommands, and run's full option list, so one screen shows everything.
148	void print_usage(std::FILE* out) {
149	  std::fputs("usage: andesim <command> [options] <ELF> [-- <engine args>]\n\n",
150	             out);
151	  std::fputs("Multi-engine driver for the Andes simulators (QEMU + vsim).\n\n",
152	             out);
153	  print_run_block(out);
154	  std::fputs("\n", out);
155	  print_list_block(out);
156	  std::fputs("\n", out);
157	  print_doctor_block(out);
158	  std::fputs(
159	      "\n'andesim run --help' / 'andesim list --help' for per-command "
160	      "detail.\n",
161	      out);
162	}
163	
164	// Per-command `andesim <cmd> --help`: the matching slice of the same tree.
165	void print_subcommand_help(const Subcommand& sc, std::FILE* out) {
166	  if (sc.name == "run") { print_run_block(out); return; }
167	  if (sc.name == "list") { print_list_block(out); return; }
168	  if (sc.name == "doctor") { print_doctor_block(out); return; }
169	  // A Hidden/unfinished command: a stable usage line, no advertised detail.
170	  std::fprintf(out, "usage: andesim %.*s [args...]\n",
171	               static_cast<int>(sc.name.size()), sc.name.data());
172	}
173	
174	}  // namespace
175	
176	int main(int argc, char** argv) {
177	  using namespace andes_sim;
178	
179	  Cli cli = parse_cli(argc, argv);
180	  if (!cli.error.empty()) {
181	    std::fprintf(stderr, "andesim: %s\n", cli.error.c_str());
182	    return 2;
183	  }
184	
185	  if (cli.subcommand.empty()) {  // no command, or top-level -h
186	    if (cli.help) {
187	      print_usage(stdout);
188	      return 0;
189	    }
190	    print_usage(stderr);
191	    return 2;
192	  }
193	
194	  const Subcommand* sc = find(cli.subcommand);
195	  if (!sc) {
196	    std::fprintf(stderr, "andesim: unknown command '%s'\n\n",
197	                 cli.subcommand.c_str());
198	    print_usage(stderr);
199	    return 2;
200	  }
201	
202	  if (cli.help) {
203	    print_subcommand_help(*sc, stdout);
204	    return 0;
205	  }
206	
207	  if (cli.subcommand == "list") return cmd_list(cli);
208	  if (cli.subcommand == "doctor") return cmd_doctor(cli);
209	  if (cli.subcommand == "run") return cmd_run(cli);
210	
211	  // Remaining subcommands stub out until their handler lands (run/doctor arrive
212	  // feature by feature). Resolve the repo root so the discovery path -- which
213	  // every handler relies on -- stays live and observable from the scaffold.
214	  std::string root;
215	  try {
216	    root = repo_root().string();
217	  } catch (const std::exception& e) {
218	    root = std::string("<unknown: ") + e.what() + ">";
219	  }
220	  std::fprintf(stderr, "andesim %s: not yet implemented (repo root: %s)\n",
221	               cli.subcommand.c_str(), root.c_str());
222	  return 3;
223	}
