123	// `run --mode cycle` presentation: spawn the engine, hiding its startup banner
124	// and verbose [info] log (VsimFilter), relaying only the program's own output
125	// and any real diagnostics, then restate the lifted cycle count as andesim's own
126	// one-line result under the [andesim] prefix. The count is printed AFTER the run
127	// (the engine logs it at exit), so it follows the program output. Returns the
128	// engine exit code. Unlike fast's exec_passthrough, the parent stays alive to
129	// filter -- fine, because cycle (without --gdb) is a batch run, not interactive.
130	int run_cycle_clean(const std::vector<std::string>& argv) {
131	  VsimFilter filter;
132	  const int rc = run_line_filtered(
133	      argv, [&filter](int stream, std::string_view line) {
134	        std::FILE* dst = nullptr;
135	        switch (filter.classify(stream, line)) {
136	          case VsimFilter::Dest::kStdout: dst = stdout; break;
137	          case VsimFilter::Dest::kStderr: dst = stderr; break;
138	          case VsimFilter::Dest::kDrop: return;
139	        }
140	        std::fwrite(line.data(), 1, line.size(), dst);
141	        std::fputc('\n', dst);
142	      });
143	  if (const std::optional<uint64_t> c = filter.cycles())
144	    std::printf("[andesim] %llu cycles\n", static_cast<unsigned long long>(*c));
145	  return rc;
146	}
147	
148	// The standalone spine shared by `fast` and `cycle`: both take a single ELF,
149	// then run the resolved engine standalone with `extra` (model flags the
150	// framework forwards, e.g. fast's -m) followed by the post-`--` args verbatim.
151	// `clean_output` picks how the engine's output is presented: fast inherits the
152	// stdio transparently (exec_passthrough -- an interactive gdbstub / monitor /
153	// semihosting console works unchanged); cycle filters out the engine's banner +
154	// [info] noise and restates the cycle count (run_cycle_clean). Either way the
155	// exit code propagates. The per-model engine + selection are resolved by the
156	// caller; `model` here only labels the positional diagnostics.
157	int run_standalone(const Cli& cli, const EngineDescriptor& eng,
158	                   const char* model, const std::vector<std::string>& extra = {},
159	                   bool clean_output = false) {
160	  if (int rc = check_one_elf(cli, model)) return rc;
161	  // QEMU's -bios flag searches its data directory for relative paths rather
162	  // than the CWD; resolve to absolute so both QEMU and vsim find the ELF.
163	  const std::string elf = abs_elf(cli.positional[0], "--mode " + std::string(model));
164	  if (elf.empty()) return 2;
165	  std::vector<std::string> args = extra;
166	  args.insert(args.end(), cli.passthrough.begin(), cli.passthrough.end());
167	  std::string err;
168	  const std::vector<std::string> argv =
169	      passthrough_argv(eng, "standalone", elf, args, err);
170	  if (!err.empty()) {
171	    std::fprintf(stderr, "andesim run: %s\n", err.c_str());
172	    return 2;
173	  }
174	  // --dry-run: print the exact engine command and stop, spawning nothing -- the
175	  // full qemu/vsim command (incl. -bios <elf> and any post-`--`).
176	  if (cli.dry_run)
177	    return print_dry_run({argv}, {std::string("standalone [") + eng.id + "]"});
178	  return clean_output ? run_cycle_clean(argv) : exec_passthrough(argv);
179	}
180	
181	// `run --mode fast`: QEMU alone, functional, transparent passthrough. Needs
182	// only the built-in qemu descriptor, so it resolves that directly rather than
183	// discover_engines(), which would spawn a --describe subprocess per Verilator
184	// build only to discard them all here.
185	int run_fast(const Cli& cli) {
186	  // fast is QEMU-only; an explicit engine must name 'qemu64' (rv64) or 'qemu32'.
187	  if (!cli.engine.empty() && cli.engine != kQemuId64 && cli.engine != kQemuId32) {
188	    std::fprintf(stderr,
189	                 "andesim run --mode fast: engine must be 'qemu64' or 'qemu32', "
190	                 "got '%s'\n",
191	                 cli.engine.c_str());
192	    return 2;
193	  }
194	  // --mem-size forwards a plain `-m`; QEMU validates it (as-is, no mmap, no
195	  // default injected). It precedes the post-`--` args, so a user's own -m wins.
196	  std::string err;
197	  std::vector<std::string> extra = qemu_m_args(cli.mem_size, err);
198	  if (!err.empty()) {
199	    std::fprintf(stderr, "andesim run --mode fast: %s\n", err.c_str());
200	    return 2;
201	  }
202	  // --gdb: inject QEMU's built-in GDB stub and pause at startup.
203	  if (cli.gdb) {
204	    const std::string port = cli.gdb_port.empty() ? "1234" : cli.gdb_port;
205	    extra.push_back("-gdb");
206	    extra.push_back("tcp::" + port);
207	    extra.push_back("-S");
208	  }
209	  // Pick rv32 vs rv64. An explicit --engine (qemu32/qemu64) wins; otherwise read
210	  // the ELF's class so an rv32 program lands on qemu-system-riscv32 instead of
211	  // the rv64 default. Warn (do not fail) if an explicit choice contradicts the
212	  // ELF -- the override is the user's call.
213	  const int elf_w = cli.positional.empty() ? 0 : elf_xlen(cli.positional[0]);
214	  int xlen;
215	  if (cli.engine == kQemuId32) xlen = 32;
216	  else if (cli.engine == kQemuId64) xlen = 64;
217	  else xlen = elf_w ? elf_w : 64;  // no explicit engine: follow the ELF (else rv64)
218	  // Only an explicit engine can disagree with the ELF (when none is given, xlen
219	  // == elf_w), so this guard already implies an explicit --engine.
220	  if (elf_w && elf_w != xlen)
221	    std::fprintf(stderr,
222	                 "[andesim] --mode fast: --engine %s is rv%d but the ELF is rv%d "
223	                 "(running as rv%d)\n",
224	                 cli.engine.c_str(), xlen, elf_w, xlen);
225	  return run_standalone(cli, builtin_qemu_arch(xlen), "fast", extra);
226	}
227	
228	// Block until 127.0.0.1:`port` is LISTENing (or `timeout_ms` elapses). vsim opens
229	// its --jtag-port only after it has reset and halted the hart, so the debugger we
230	// exec next must not race ahead of it -- OpenOCD/ICEman do not retry the bitbang
231	// connect, and a missed connect leaves the session dead. Non-intrusive: scans
232	// /proc/net/tcp rather than connecting (a probe connection would land in vsim's
233	// single debugger slot). Returns false on timeout.
234	static bool wait_for_jtag_port(uint16_t port, int timeout_ms = 20000) {
235	  constexpr int kPollMs = 50;
236	  for (int waited = 0; waited <= timeout_ms; waited += kPollMs) {
237	    if (std::FILE* f = std::fopen("/proc/net/tcp", "re")) {
238	      char line[512];
239	      while (std::fgets(line, sizeof line, f)) {
240	        // cols: sl  local_address(IP:port hex)  rem_address  st  ...
241	        // "%*8x:%x" skips the 8-hex-digit IPv4 and reads the local port; the
242	        // 0A (TCP_LISTEN) filter also drops the non-hex header row.
243	        unsigned lport = 0, st = 0;
244	        if (std::sscanf(line, "%*s %*8x:%x %*s %x", &lport, &st) == 2
245	            && st == 0x0A && lport == port) {
246	          std::fclose(f);
247	          return true;
248	        }
249	      }
250	      std::fclose(f);
251	    }
252	    std::this_thread::sleep_for(std::chrono::milliseconds(kPollMs));
253	  }
254	  return false;
255	}
