11	// Numeric value of a bare-hex PC string from resolve_pc. resolve_pc already
12	// validated the digits; an absurd >64-bit address (out_of_range) yields false,
13	// so the equal-ROI guard simply skips it (the bogus address fails downstream).
14	bool hex_pc(const std::string& s, uint64_t& out) {
15	  try {
16	    std::size_t pos = 0;
17	    out = std::stoull(s, &pos, 16);
18	    return pos == s.size();
19	  } catch (...) {
20	    return false;
21	  }
22	}
