73	LegTriggerArgs leg_trigger_args(const Trigger& t, const std::string& role,
74	                                std::string& err) {
75	  err.clear();
76	  LegTriggerArgs out;
77	  if (t.kind == "marker") return out;  // markers detected by plugin/vsim, not argv
78	
79	  const bool fast = role == "fast-leg";
80	  const bool accurate = role == "accurate-leg";
81	  if (!fast && !accurate) return out;  // other roles carry no trigger args
82	
83	  // Required-param lookup. A missing key is a caller bug; surface it (don't
84	  // throw) so plan_argvs can report which step failed.
85	  auto param = [&](const char* key) -> const std::string* {
86	    auto it = t.params.find(key);
87	    if (it == t.params.end()) {
88	      err = "trigger '" + t.kind + "' missing param '" + key + "'";
89	      return nullptr;
90	    }
91	    return &it->second;
92	  };
93	
94	  if (t.kind == "pc") {
95	    if (fast) {
96	      if (const std::string* p = param("enter_pc"))
97	        out.plugin_suffix = ",enter_pc=" + *p;
98	    } else if (const std::string* p = param("exit_pc")) {
99	      out.extra = {"--hybrid-exit-pc", *p};
100	    }
101	    return out;
102	  }
103	
104	  // verify oracle leg (verify_oracle F4): a pure-QEMU drain at the ROI exit
105	  // boundary, sampling at vsim's actual halt pc (drain_pc -- the DMI halt
106	  // lands a few insns past the trigger, and the comparison is only valid at
107	  // the same architectural point). qemu-only: the oracle plan has no
108	  // accurate leg.
109	  if (t.kind == "verify-marker" || t.kind == "verify-pc") {
110	    if (!fast) return out;
111	    std::string suffix = ",exit_marker=1";
112	    if (t.kind == "verify-pc") {
113	      const std::string* p = param("exit_pc");
114	      if (!p) return out;
115	      suffix = ",exit_pc=" + *p;
116	    }
117	    if (const std::string* p = param("drain_pc"))
118	      out.plugin_suffix = suffix + ",drain_pc=" + *p;
119	    return out;
120	  }
121	
122	  err = "unknown trigger kind '" + t.kind + "'";
123	  return out;
124	}
