126	std::vector<std::vector<std::string>> plan_argvs(
127	    const Plan& plan, const std::vector<EngineDescriptor>& engines,
128	    const std::string& workdir, const RuntimeCtx& ctx, std::string& err) {
129	  std::vector<std::vector<std::string>> out;
130	  out.reserve(plan.steps.size());
131	  std::string prev_state_out;  // empty for the cold first leg
132	
133	  // hw-config sync: {vlen} comes from the accurate-leg engine's descriptor.
134	  long vlen = 0;
135	  // LM content transport (ROADMAP_ilm_dlm F3) + HVM (ROADMAP_hvm F3): the
136	  // accurate engine's memory sizes (bytes, from its descriptor) arm the QEMU
137	  // plugin's sidecar drain and the vsim leg's --ilm/--dlm/--hvm backdoor
138	  // load. 0 = that engine has no such memory -> neither leg grows an arg.
139	  long ilm_size = 0, dlm_size = 0, hvm_size = 0;
140	  for (const Step& s : plan.steps)
141	    if (s.role == "accurate-leg")
142	      if (const EngineDescriptor* e = find_engine(engines, s.engine_id)) {
143	        if (e->vlen > 0) vlen = e->vlen;
144	        if (e->ilm_size > 0) ilm_size = e->ilm_size;
145	        if (e->dlm_size > 0) dlm_size = e->dlm_size;
146	        if (e->hvm_size > 0) hvm_size = e->hvm_size;
147	      }
148	  const std::string vlen_str = std::to_string(synced_vlen(vlen));
149	  std::string lm_suffix;
150	  if (ilm_size > 0) lm_suffix += ",ilm_size=" + std::to_string(ilm_size);
151	  if (dlm_size > 0) lm_suffix += ",dlm_size=" + std::to_string(dlm_size);
152	  if (hvm_size > 0) lm_suffix += ",hvm_size=" + std::to_string(hvm_size);
153	
154	  for (size_t i = 0; i < plan.steps.size(); ++i) {
155	    const Step& step = plan.steps[i];
156	    const EngineDescriptor* eng = find_engine(engines, step.engine_id);
157	    if (!eng) {
158	      err = "plan step " + std::to_string(i) + ": unknown engine '" +
159	            step.engine_id + "'";
160	      return {};
161	    }
162	    const std::vector<std::string>* tmpl = eng->invoke_for(step.role);
163	    if (!tmpl) {
164	      err = "plan step " + std::to_string(i) + ": engine '" + step.engine_id +
165	            "' has no invoke template for role '" + step.role + "'";
166	      return {};
167	    }
168	
169	    std::string trig_err;
170	    const LegTriggerArgs lt = leg_trigger_args(step.trigger, step.role, trig_err);
171	    if (!trig_err.empty()) {
172	      err = "plan step " + std::to_string(i) + ": " + trig_err;
173	      return {};
174	    }
175	
176	    const std::string state_out = state_path(workdir, i);
177	    // {plugin_args} is the qemu plugin comma-suffix: trigger args (empty for
178	    // marker) plus the LM sidecar-drain args (empty for a no-LM engine).
179	    // {trigger} is its compatibility alias -- the name templates used before
180	    // non-trigger args joined the suffix (build_argv ignores unused keys).
181	    const std::string plugin_args = lt.plugin_suffix + lm_suffix;
182	    const std::map<std::string, std::string> m = {
183	        {"bin", eng->bin_path},
184	        {"elf", plan.elf},
185	        {"plugin", ctx.plugin_path},
186	        {"mmap", ctx.mmap_path},
187	        {"mmap_size", std::to_string(ctx.mem_size)},
188	        {"mmap_base", ctx.mmap_base},
189	        {"state_in", prev_state_out},
190	        {"state_out", state_out},
191	        {"plugin_args", plugin_args},
192	        {"trigger", plugin_args},
193	        {"vlen", vlen_str},
194	    };
195	    std::vector<std::string> argv = build_argv(*tmpl, m, err);
196	    if (!err.empty()) {
197	      err = "plan step " + std::to_string(i) + ": " + err;
198	      return {};
199	    }
200	    // The QEMU producer leg loads the accurate engine's ISA via -readconfig (its
201	    // config.inc distilled to per-extension globals), so QEMU1 executes the same
202	    // extensions the engine models. Empty => keep the descriptor's default -cpu.
203	    if (step.role == "fast-leg" && !ctx.qemu_cfg.empty()) {
204	      argv.push_back("-readconfig");
205	      argv.push_back(ctx.qemu_cfg);
206	    }
207	    // LM content transport (F3): point the vsim leg at the sidecars its
208	    // producer drained next to state_in (--ilm/--dlm backdoor load).
209	    if (step.role == "accurate-leg") {
210	      if (ilm_size > 0) {
211	        argv.push_back("--ilm");
212	        argv.push_back(prev_state_out + ".ilm");
213	      }
214	      if (dlm_size > 0) {
215	        argv.push_back("--dlm");
216	        argv.push_back(prev_state_out + ".dlm");
217	      }
218	      if (hvm_size > 0) {
219	        argv.push_back("--hvm");
220	        argv.push_back(prev_state_out + ".hvm");
221	      }
222	    }
223	    // Trigger's vsim tokens, then user-forwarded per-leg flags -- both verbatim
224	    // after the filled template (matches tests/e2e.sh's ordering).
225	    argv.insert(argv.end(), lt.extra.begin(), lt.extra.end());
226	    argv.insert(argv.end(), step.extra_args.begin(), step.extra_args.end());
227	    out.push_back(std::move(argv));
228	    prev_state_out = state_out;
229	  }
230	  err.clear();
231	  return out;
232	}
