234	PlanResult run_plan(const Plan& plan,
235	                    const std::vector<EngineDescriptor>& engines,
236	                    const PlanOptions& opts) {
237	  PlanResult res;
238	  if (plan.steps.empty()) {
239	    res.error = "plan has no steps";
240	    return res;
241	  }
242	
243	  // Acquire the shared mmap: allocate one (and own it) when none is pinned.
244	  std::string mmap_path = plan.mmap_path;
245	  const bool own_mmap = mmap_path.empty();
246	  if (own_mmap) {
247	    std::string err;
248	    // L26/F2: back the mmap with one V-scratch page above the program's RAM.
249	    mmap_path = allocate(physical_mmap_bytes(plan.mem_size), err);
250	    if (mmap_path.empty()) {
251	      res.error = err;
252	      return res;
253	    }
254	  }
255	
256	  // A private dir for the threaded drain files.
257	  std::error_code ec;
258	  fs::path workdir = fs::temp_directory_path(ec) / "andesim-plan-XXXXXX";
259	  std::string tmpl = workdir.string();
260	  std::vector<char> tbuf(tmpl.begin(), tmpl.end());
261	  tbuf.push_back('\0');
262	  const char* made = ::mkdtemp(tbuf.data());
263	  if (!made) {
264	    if (own_mmap) ::unlink(mmap_path.c_str());
265	    res.error = "failed to create plan work dir";
266	    return res;
267	  }
268	  const std::string wd = made;
269	
270	  RuntimeCtx ctx;
271	  ctx.mmap_path = mmap_path;
272	  // L26/F2: the legs (QEMU backend size, vsim --shared-mem-size) see the
273	  // PHYSICAL window -- program RAM plus the V-scratch page. The program's own
274	  // linker script still uses only --mem-size, so the scratch page sits above
275	  // everything it can address.
276	  ctx.mem_size = physical_mmap_bytes(plan.mem_size);
277	  ctx.plugin_path = resolve_plugin(opts.plugin_path);  // mmap_base keeps its "0x0" default
278	
279	  // Match the QEMU producer leg's ISA to the accurate engine: ask that engine
280	  // for a QEMU -readconfig cfg distilled from its config.inc. Tolerant -- an
281	  // engine without --print-qemu-config leaves qemu_cfg empty (the parser throws
282	  // on the unknown flag -> non-zero exit), so the fast leg keeps its -cpu.
283	  for (const Step& s : plan.steps)
284	    if (s.role == "accurate-leg")
285	      if (const EngineDescriptor* e = find_engine(engines, s.engine_id);
286	          e && !e->bin_path.empty()) {
287	        ctx.qemu_cfg = stage_qemu_cfg(
288	            wd, run_process({e->bin_path, "--print-qemu-config"}, kQemuCfgProbeMs));
289	        break;
290	      }
291	
292	  std::string err;
293	  const std::vector<std::vector<std::string>> argvs =
294	      plan_argvs(plan, engines, wd, ctx, err);
295	  if (!err.empty()) {
296	    res.error = err;
297	  } else if (opts.dry_run) {
298	    // Build-only: the argvs are fully resolved (placeholders, staged qemu_cfg,
299	    // threaded state paths) -- record them for the caller to print, spawn none.
300	    res.argvs = argvs;
301	  } else {
302	    res.argvs = argvs;
303	    for (size_t i = 0; i < argvs.size(); ++i) {
304	      const RunResult r = run_process(argvs[i], opts.timeout_ms);
305	      if (r.spawn_failed) {
306	        res.error = "plan step " + std::to_string(i) + ": failed to spawn";
307	        break;
308	      }
309	      if (r.timed_out) {
310	        res.error = "plan step " + std::to_string(i) + ": timed out after " +
311	                    std::to_string(opts.timeout_ms) + " ms";
312	        break;
313	      }
314	      if (r.rc != opts.expect_rc) {
315	        res.error = plan_step_rc_error(i, plan.steps[i], opts.expect_rc, r.rc);
316	        break;
317	      }
318	      const StateFile sf = read_state_file(state_path(wd, i));
319	      if (!sf.ok()) {
320	        res.error = "plan step " + std::to_string(i) + ": " + sf.error;
321	        break;
322	      }
323	      res.phases.push_back({sf.st.mcycle, sf.st.minstret, r.out, sf.st});
324	    }
325	  }
326	
327	  fs::remove_all(wd, ec);
328	  if (own_mmap) ::unlink(mmap_path.c_str());
329	  return res;
330	}
