28	// Human-readable byte count: "8.0 GiB", "512.0 MiB", "1024 B". Mirrors
29	// hsim_shm._format_bytes (one decimal, TiB/GiB/MiB/KiB, else "N B").
30	std::string format_bytes(long long n) {
31	  struct Unit {
32	    const char* suffix;
33	    long long mul;
34	  };
35	  static const Unit units[] = {
36	      {"TiB", 1024LL * 1024 * 1024 * 1024},
37	      {"GiB", 1024LL * 1024 * 1024},
38	      {"MiB", 1024LL * 1024},
39	      {"KiB", 1024LL},
40	  };
41	  for (const Unit& u : units) {
42	    if (n >= u.mul) {
43	      char buf[64];
44	      std::snprintf(buf, sizeof(buf), "%.1f %s",
45	                    static_cast<double>(n) / static_cast<double>(u.mul),
46	                    u.suffix);
47	      return buf;
48	    }
49	  }
50	  return std::to_string(n) + " B";
51	}
