55	long long parse_size(const std::string& spec, std::string& err) {
56	  static const std::regex re(R"(\s*(\d+(?:\.\d+)?)\s*([KMGT]?)\s*)",
57	                             std::regex::icase);
58	  std::smatch m;
59	  if (!std::regex_match(spec, m, re)) {
60	    err = "invalid mmap size '" + spec +
61	          "': expected <number>[K|M|G|T] (e.g. '128M', '8G', '1024')";
62	    return 0;
63	  }
64	  const double num = std::stod(m[1].str());
65	  long long mult = 1;
66	  if (m[2].length()) {
67	    switch (std::toupper(static_cast<unsigned char>(m[2].str()[0]))) {
68	      case 'K': mult = 1024LL; break;
69	      case 'M': mult = 1024LL * 1024; break;
70	      case 'G': mult = 1024LL * 1024 * 1024; break;
71	      case 'T': mult = 1024LL * 1024 * 1024 * 1024; break;
72	    }
73	  }
74	  // Truncate toward zero like Python int(float(num) * multiplier).
75	  const long long size =
76	      static_cast<long long>(num * static_cast<double>(mult));
77	  if (size <= 0) {
78	    err = "invalid mmap size '" + spec + "': must be > 0";
79	    return 0;
80	  }
81	  err.clear();
82	  return size;
83	}
84	
85	// L26/F2: physical mmap = program RAM + one V-scratch page. See shm.hpp.
86	long long physical_mmap_bytes(long long program_bytes) {
87	  return program_bytes + HYBRID_V_SCRATCH_BYTES;
88	}
89	
90	long long max_program_mem_bytes() {
91	  // AE350 DRAM window is 2 GiB; leave room for the scratch page on top.
92	  constexpr long long kAe350DramWindowBytes = 2LL * 1024 * 1024 * 1024;
93	  return kAe350DramWindowBytes - HYBRID_V_SCRATCH_BYTES;
94	}
95	
96	std::vector<std::string> wsl_warnings(const std::string& proc_version,
97	                                      const std::string& repo_dir,
98	                                      const std::vector<MmapTier>& tiers) {
99	  std::string lower = proc_version;
100	  for (char& c : lower) c = static_cast<char>(std::tolower(
101	      static_cast<unsigned char>(c)));
102	  if (lower.find("microsoft") == std::string::npos) return {};
103	
104	  std::vector<std::string> warns;
105	  warns.push_back(
106	      "WSL2: /dev/shm is capped by the WSL VM memory; raise memory= in "
107	      ".wslconfig if tier 1 is too small");
108	  if (repo_dir.starts_with("/mnt/"))
109	    warns.push_back("repo is under /mnt/ (drvfs): slow, and MAP_SHARED is "
110	                    "not coherent -- keep the repo in the Linux home (~)");
111	  for (const MmapTier& t : tiers)
112	    if (t.dir.starts_with("/mnt/"))
113	      warns.push_back("mmap dir " + t.dir +
114	                      " is under /mnt/ (drvfs): MAP_SHARED is not coherent "
115	                      "there -- use a Linux-side dir");
116	  return warns;
117	}
118	
119	std::vector<std::string> qemu_m_args(const std::string& spec,
120	                                     std::string& err) {
121	  err.clear();
122	  if (spec.empty()) return {};
123	  const long long bytes = parse_size(spec, err);
124	  if (!err.empty()) {
125	    err = "--mem-size: " + err;
126	    return {};
127	  }
128	  if (bytes % (1024 * 1024) != 0) {
129	    err = "--mem-size '" + spec +
130	          "': QEMU's -m takes whole MiB; round to a multiple of 1M";
131	    return {};
132	  }
133	  return {"-m", std::to_string(bytes / (1024 * 1024)) + "M"};
134	}
135	
136	MmapDirChoice resolve_mmap_dir(
137	    const std::vector<MmapTier>& tiers, long long size,
138	    const std::function<long long(const std::string&)>& probe,
139	    std::string& err) {
140	  const long long need = size + kMmapSafetyMargin;
141	  std::vector<std::string> reasons;
142	  for (const MmapTier& t : tiers) {
143	    const long long free = probe(t.dir);
144	    if (free >= need) {
145	      err.clear();
146	      std::string note;
147	      for (size_t i = 0; i < reasons.size(); i++)
148	        note += (i ? "; " : "") + reasons[i];
149	      return {t.dir, note};
150	    }
151	    reasons.push_back(free < 0 ? t.label + " missing"
152	                               : t.label + " too small (" +
153	                                     format_bytes(free) + " free)");
154	  }
155	  err = "no mmap directory can hold " + format_bytes(size) +
156	        " + 256 MiB margin: ";
157	  for (size_t i = 0; i < reasons.size(); i++)
158	    err += (i ? "; " : "") + reasons[i];
159	  err += "; set HSIM_MMAP_DIR to a directory with enough free space";
160	  return {"", ""};
161	}
162	
163	std::vector<MmapTier> mmap_tiers() {
164	  if (const char* pinned = std::getenv("HSIM_MMAP_DIR"); pinned && pinned[0])
165	    return {{pinned, "HSIM_MMAP_DIR='" + std::string(pinned) + "'"}};
166	
167	  std::string cache;
168	  if (const char* xdg = std::getenv("XDG_CACHE_HOME"); xdg && xdg[0])
169	    cache = std::string(xdg) + "/andesim";
170	  else if (const char* home = std::getenv("HOME"); home && home[0])
171	    cache = std::string(home) + "/.cache/andesim";
172	
173	  std::vector<MmapTier> tiers = {{"/dev/shm", "/dev/shm"}};
174	  if (!cache.empty()) {
175	    std::error_code ec;
176	    std::filesystem::create_directories(cache, ec);  // probe needs it to exist
177	    tiers.push_back({cache, cache});
178	  }
179	  return tiers;
180	}
181	
182	std::string allocate(long long size, std::string& err,
183	                     const std::string& prefix) {
184	  const MmapDirChoice choice =
185	      resolve_mmap_dir(mmap_tiers(), size, free_bytes, err);
186	  if (choice.dir.empty()) return "";
187	
188	  std::string tmpl = choice.dir + "/" + prefix + "XXXXXX";
189	  std::vector<char> buf(tmpl.begin(), tmpl.end());
190	  buf.push_back('\0');
191	  const int fd = mkstemp(buf.data());
192	  if (fd < 0) {
193	    err = "failed to create mmap file in " + choice.dir;
194	    return "";
195	  }
196	  close(fd);
197	  const std::string path(buf.data());
198	  if (truncate(path.c_str(), size) != 0) {
199	    unlink(path.c_str());
200	    err = "failed to size mmap file " + path;
201	    return "";
202	  }
203	
204	  std::string line = "[hsim mmap] " + format_bytes(size) + " at " +
205	                     choice.dir + " (free: " + format_bytes(free_bytes(choice.dir)) + ")";
206	  if (!choice.note.empty()) line += " (fallback: " + choice.note + ")";
207	  std::printf("%s\n", line.c_str());
208	  std::fflush(stdout);
209	  err.clear();
210	  return path;
211	}
