1	// `andesim doctor` -- read-only environment health.
2	//
3	// The four carried-over sections (artifacts, submodules, toolchain, runtime)
4	// plus the Summary line are a faithful C++ port of the Python hsim `cmd_doctor`,
5	// kept byte-identical so the parity flywheel stays green. The detail strings
6	// point at scripts/build_all.sh -- the build entry point, since the build
7	// command moved out of the binary into that script (hsim's doctor matches).
8	// After Summary the driver appends an `engines:` readout sourced from F2
9	// discovery -- new surface, INFO-tagged, never affecting the exit code (which
10	// stays 1 iff any FAIL row, exactly as the golden).
11	#include <algorithm>
12	#include <cctype>
13	#include <cstdio>
14	#include <cstdlib>
15	#include <filesystem>
16	#include <fstream>
17	#include <string>
18	#include <vector>
19	
20	#include <sys/statvfs.h>
21	#include <unistd.h>
22	
23	#include "cli.hpp"
24	#include "engine_registry.hpp"
25	#include "repo_root.hpp"
