34	// One diagnostic row. status is PASS | FAIL | WARN | INFO; only PASS/FAIL/WARN
35	// feed the summary, and only FAIL gates the exit code.
36	struct Row {
37	  std::string name;
38	  std::string status;
39	  std::string detail;
40	};
41	
42	// Strip every leading and trailing `c` from `s` (mirrors Python str.strip(c)).
43	std::string strip_char(std::string s, char c) {
44	  size_t b = 0, e = s.size();
45	  while (b < e && s[b] == c) ++b;
46	  while (e > b && s[e - 1] == c) --e;
47	  return s.substr(b, e - b);
48	}
49	
50	// --- artifacts --------------------------------------------------------------
51	
52	std::vector<Row> doctor_artifacts() {
53	  const fs::path root = repo_root();
54	  struct A {
55	    const char* label;
56	    const char* env;
57	    fs::path def;
58	  };
59	  // The vsim/qemu defaults come straight from the registry's resolvers
60	  // (vsim_scan_dir / builtin_qemu_arch), so doctor reports the same paths the
61	  // engine would use instead of re-deriving the env -> QEMU_BIN_DIR -> legacy
62	  // tiers. Env overrides still match hsim's _ARTIFACT_ENV; order (vsim, qemu,
63	  // plugin) mirrors the golden's dict order.
64	  const A arts[] = {
65	      {"vsim", "VSIM_BIN", vsim_scan_dir() / "sim_ax45mpv_premium"},
66	      {"qemu64", "VSIM_QEMU", builtin_qemu_arch(64).bin_path},
67	      {"plugin", "VSIM_PLUGIN", default_plugin_path()},
68	  };
69	  std::vector<Row> rows;
70	  for (const A& a : arts) {
71	    const char* ov = std::getenv(a.env);
72	    fs::path p = (ov && *ov) ? fs::path(ov) : a.def;
73	    if (fs::is_regular_file(p))
74	      rows.push_back({a.label, "PASS", p.string()});
75	    else
76	      rows.push_back(
77	          {a.label, "FAIL", "missing " + p.string() + " -- run scripts/build_all.sh"});
78	  }
79	
80	  const fs::path fix = root / "tests" / "fixtures";
81	  size_t elfs = 0;
82	  std::error_code ec;
83	  if (fs::is_directory(fix, ec))
84	    for (const auto& e : fs::directory_iterator(fix, ec))
85	      if (e.path().extension() == ".elf") ++elfs;
86	  if (elfs > 0)
87	    rows.push_back(
88	        {"fixtures", "PASS", std::to_string(elfs) + " ELFs in " + fix.string()});
89	  else
90	    rows.push_back({"fixtures", "FAIL",
91	                    "no *.elf in " + fix.string() +
92	                        " -- run make -C tests/fixtures"});
93	  return rows;
94	}
