96	// --- submodules -------------------------------------------------------------
97	
98	std::vector<Row> doctor_submodules() {
99	  const fs::path root = repo_root();
100	  struct M {
101	    const char* name;
102	    fs::path marker;
103	    const char* rel;  // marker, repo-relative (the PASS detail)
104	  };
105	  // QEMU and vsim are no longer submodules -- both are integrated as prebuilt
106	  // external binaries, checked in the artifacts section (qemu/vsim rows) via
107	  // VSIM_QEMU / VSIM_BIN_DIR. The one remaining submodule is the shared ABI.
108	  const M ms[] = {
109	      {"include/ (abi)", root / "include" / "hybrid" / "state_abi.h",
110	       "include/hybrid/state_abi.h"},
111	  };
112	  std::vector<Row> rows;
113	  for (const M& m : ms) {
114	    if (fs::is_regular_file(m.marker))
115	      rows.push_back({m.name, "PASS", m.rel});
116	    else
117	      rows.push_back({m.name, "FAIL",
118	                      "missing " + m.marker.string() +
119	                          " -- run 'git submodule update --init --recursive'"});
120	  }
121	  return rows;
122	}
123	
124	// --- toolchain --------------------------------------------------------------
125	
126	// First PATH directory holding an executable non-directory named `tool`, joined
127	// the way shutil.which reports it (dir + '/' + tool). "" if not found.
128	std::string which(const std::string& tool) {
129	  const char* path = std::getenv("PATH");
130	  if (!path) return "";
131	  const std::string p(path);
132	  for (size_t i = 0; i <= p.size();) {
133	    size_t j = p.find(':', i);
134	    if (j == std::string::npos) j = p.size();
135	    std::string dir = p.substr(i, j - i);
136	    i = j + 1;
137	    if (dir.empty()) continue;
138	    std::string cand = dir.back() == '/' ? dir + tool : dir + "/" + tool;
139	    std::error_code ec;
140	    if (::access(cand.c_str(), X_OK) == 0 && !fs::is_directory(cand, ec))
141	      return cand;
142	  }
143	  return "";
144	}
145	
146	// Match `^\s*(?:export\s+)?HYBRID_TOOLCHAIN\s*=\s*(.+?)\s*$`; on match set `out`
147	// to the value with surrounding whitespace, then double, then single quotes
148	// stripped (mirrors hsim._read_hybrid_toolchain).
149	bool parse_toolchain_line(const std::string& line, std::string& out) {
150	  size_t i = 0, n = line.size();
151	  auto skip_ws = [&] {
152	    while (i < n && std::isspace(static_cast<unsigned char>(line[i]))) ++i;
153	  };
154	  skip_ws();
155	  const std::string kw = "export";
156	  if (line.compare(i, kw.size(), kw) == 0 && i + kw.size() < n &&
157	      std::isspace(static_cast<unsigned char>(line[i + kw.size()]))) {
158	    i += kw.size();
159	    skip_ws();
160	  }
161	  const std::string key = "HYBRID_TOOLCHAIN";
162	  if (line.compare(i, key.size(), key) != 0) return false;
163	  i += key.size();
164	  skip_ws();
165	  if (i >= n || line[i] != '=') return false;
166	  std::string rest = line.substr(i + 1);  // everything after '='
167	  if (rest.empty()) return false;         // regex (.+?) needs >= 1 char
168	  size_t b = 0, e = rest.size();
169	  while (b < e && std::isspace(static_cast<unsigned char>(rest[b]))) ++b;
170	  while (e > b && std::isspace(static_cast<unsigned char>(rest[e - 1]))) --e;
171	  std::string val = strip_char(rest.substr(b, e - b), '"');
172	  out = strip_char(val, '\'');
173	  return true;
174	}
175	
176	// HYBRID_TOOLCHAIN: env first (non-empty wins), else the first matching
177	// assignment in config.env. "" if neither yields a value.
178	std::string read_hybrid_toolchain() {
179	  const char* env = std::getenv("HYBRID_TOOLCHAIN");
180	  if (env && *env) return env;
181	  std::ifstream f(repo_root() / "config.env");
182	  if (!f) return "";
183	  std::string line, val;
184	  while (std::getline(f, line))
185	    if (parse_toolchain_line(line, val)) return val;
186	  return "";
187	}
188	
189	std::vector<Row> doctor_toolchain() {
190	  struct T {
191	    const char* tool;
192	    const char* hint;
193	    bool warn_only;  // a missing podman warns; ninja/make fail
194	  };
195	  const T tools[] = {
196	      {"ninja", "needed by scripts/build_all.sh of QEMU", false},
197	      {"make", "needed by scripts/build_all.sh of fixtures", false},
198	      {"podman", "needed by scripts/build_all.sh of vsim (or docker shim)", true},
199	  };
200	  std::vector<Row> rows;
201	  for (const T& t : tools) {
202	    std::string found = which(t.tool);
203	    if (!found.empty())
204	      rows.push_back({t.tool, "PASS", found});
205	    else
206	      rows.push_back({t.tool, t.warn_only ? "WARN" : "FAIL",
207	                      std::string("not on PATH -- ") + t.hint});
208	  }
209	
210	  std::string tc = read_hybrid_toolchain();
211	  if (tc.empty()) {
212	    rows.push_back({"HYBRID_TOOLCHAIN", "WARN",
213	                    "not set -- needed for fixture build (see config.env)"});
214	  } else {
215	    fs::path gcc = fs::path(tc) / "bin" / "riscv64-unknown-elf-gcc";
216	    if (fs::is_regular_file(gcc))
217	      rows.push_back({"riscv64-unknown-elf-gcc", "PASS", gcc.string()});
218	    else
219	      rows.push_back({"riscv64-unknown-elf-gcc", "FAIL",
220	                      "missing " + gcc.string() +
221	                          " -- check HYBRID_TOOLCHAIN=" + tc});
222	  }
223	  return rows;
224	}
