226	// --- runtime ----------------------------------------------------------------
227	
228	constexpr long kDefaultJobs = 8;
229	
230	std::vector<Row> doctor_runtime() {
231	  std::vector<Row> rows;
232	  long nproc = sysconf(_SC_NPROCESSORS_ONLN);
233	  if (nproc < 1) nproc = 1;
234	  rows.push_back({"nproc", "INFO", std::to_string(nproc)});
235	
236	  std::error_code ec;
237	  if (fs::is_directory("/dev/shm", ec)) {
238	    struct statvfs vfs{};
239	    unsigned long long free_gb = 0;
240	    if (statvfs("/dev/shm", &vfs) == 0)
241	      free_gb = static_cast<unsigned long long>(vfs.f_bavail) * vfs.f_frsize /
242	                (1024ULL * 1024 * 1024);
243	    rows.push_back({"/dev/shm free", free_gb >= 4 ? "PASS" : "WARN",
244	                    std::to_string(free_gb) + " GB"});
245	  } else {
246	    rows.push_back({"/dev/shm", "WARN",
247	                    "not present -- e2e fixtures will fall back to $TMPDIR"});
248	  }
249	
250	  long suggested = std::min(nproc, kDefaultJobs);
251	  rows.push_back({"JOBS suggestion", "INFO",
252	                  std::to_string(suggested) + " (default cap = " +
253	                      std::to_string(kDefaultJobs) + ")"});
254	  return rows;
255	}
256	
257	// --- engines (C++-only readout, after Summary) ------------------------------
258	
259	// Reflects `list engines` from the same F2 discovery, in doctor's row idiom.
260	// INFO-tagged and printed after Summary, so it never moves the summary counts
261	// or the exit code. Discovery warnings surface as WARN rows here.
262	void print_engines_section() {
263	  Discovery disc = discover_engines();
264	  size_t w = 0;
265	  for (const EngineDescriptor& e : disc.engines) w = std::max(w, e.id.size());
266	
267	  std::printf("\nengines:\n");
268	  for (const EngineDescriptor& e : disc.engines)
269	    std::printf("  [INFO] %s  kind=%s vlen=%s triggers=%s\n",
270	                ljust(e.id, w).c_str(), e.kind.c_str(), vlen_str(e.vlen).c_str(),
271	                join(e.triggers).c_str());
272	  for (const std::string& warn : disc.warnings)
273	    std::printf("  [WARN] %s\n", warn.c_str());
274	}
275	
276	// The shared-mmap backing tiers (F1 resolver order) with their free space,
277	// plus WSL2 advice. INFO/WARN-tagged and printed after Summary like engines,
278	// so the carried-over report keeps byte-parity with the Python golden.
279	void print_mmap_section() {
280	  const std::vector<MmapTier> tiers = mmap_tiers();
281	  size_t w = 0;
282	  for (const MmapTier& t : tiers) w = std::max(w, t.label.size());
283	
284	  std::printf("\nmmap tiers:\n");
285	  int n = 0;
286	  for (const MmapTier& t : tiers) {
287	    struct statvfs vfs{};
288	    std::string free = "missing";
289	    if (statvfs(t.dir.c_str(), &vfs) == 0) {
290	      const double gib = static_cast<double>(vfs.f_bavail) * vfs.f_frsize /
291	                         (1024.0 * 1024 * 1024);
292	      char buf[32];
293	      std::snprintf(buf, sizeof(buf), "free: %.1f GiB", gib);
294	      free = buf;
295	    }
296	    std::printf("  [INFO] tier %d  %s  %s\n", ++n, ljust(t.label, w).c_str(),
297	                free.c_str());
298	  }
299	
300	  std::string proc_version;
301	  if (std::FILE* f = std::fopen("/proc/version", "r")) {
302	    char buf[512] = {};
303	    const size_t got = std::fread(buf, 1, sizeof(buf) - 1, f);
304	    proc_version.assign(buf, got);
305	    std::fclose(f);
306	  }
307	  std::error_code ec;
308	  for (const std::string& warn :
309	       wsl_warnings(proc_version, fs::current_path(ec).string(), tiers))
310	    std::printf("  [WARN] %s\n", warn.c_str());
311	}
312	
313	struct Section {
314	  const char* title;
315	  std::vector<Row> rows;
316	};
317	
318	}  // namespace
319	
320	int cmd_doctor(const Cli&) {
321	  std::vector<Section> sections = {
322	      {"artifacts", doctor_artifacts()},
323	      {"submodules", doctor_submodules()},
324	      {"toolchain", doctor_toolchain()},
325	      {"runtime", doctor_runtime()},
326	  };
327	
328	  size_t name_width = 0;
329	  for (const Section& s : sections)
330	    for (const Row& r : s.rows) name_width = std::max(name_width, r.name.size());
331	
332	  int passes = 0, fails = 0, warns = 0;
333	  for (const Section& s : sections) {
334	    std::printf("%s:\n", s.title);
335	    for (const Row& r : s.rows) {
336	      if (r.status == "PASS") ++passes;
337	      else if (r.status == "FAIL") ++fails;
338	      else if (r.status == "WARN") ++warns;
339	      std::printf("  [%-4s] %s  %s\n", r.status.c_str(),
340	                  ljust(r.name, name_width).c_str(), r.detail.c_str());
341	    }
342	    std::printf("\n");
343	  }
344	  std::printf("Summary: %d PASS, %d FAIL, %d WARN\n", passes, fails, warns);
345	
346	  print_engines_section();
347	  print_mmap_section();
348	  return fails > 0 ? 1 : 0;
349	}
