1	// `andesim list fixtures|models|engines`.
2	//
3	// `list fixtures` is a faithful C++ port of the Python hsim `parse_fixtures`
4	// + `list_fixtures`, so its output stays byte-identical to the golden driver
5	// (the parity flywheel depends on this). `list models` is new surface (the
6	// composition axis that replaced the old `--mode`). `list engines` is a
7	// scaffold until runtime discovery lands in F2.
8	#include <algorithm>
9	#include <cstdio>
10	#include <filesystem>
11	#include <fstream>
12	#include <set>
13	#include <sstream>
14	#include <string>
15	#include <vector>
16	
17	#include "cli.hpp"
18	#include "dev_mode.hpp"
19	#include "engine_registry.hpp"
20	#include "models.hpp"
21	#include "repo_root.hpp"
22	#include "strutil.hpp"
23	
24	namespace fs = std::filesystem;
25	
26	namespace andes_sim {
27	namespace {
28	
29	std::vector<std::string> read_lines(const fs::path& p, bool& ok) {
30	  std::ifstream f(p);
31	  std::vector<std::string> lines;
32	  ok = static_cast<bool>(f);
33	  if (!ok) return lines;
34	  std::string line;
35	  while (std::getline(f, line)) lines.push_back(line);
36	  return lines;
37	}
38	
39	// Match a Makefile variable assignment at column 0: `VAR :?= <body>` where
40	// VAR is [A-Z_][A-Z0-9_]*. Mirrors the Python regex anchor. On success sets
41	// `var` and `body` (the text after `=`, continuation backslash included).
42	bool parse_assignment(const std::string& line, std::string& var,
43	                      std::string& body) {
44	  const size_t n = line.size();
45	  if (n == 0) return false;
46	  char c0 = line[0];
47	  if (!((c0 >= 'A' && c0 <= 'Z') || c0 == '_')) return false;
48	  size_t p = 0;
49	  while (p < n) {
50	    char c = line[p];
51	    if ((c >= 'A' && c <= 'Z') || (c >= '0' && c <= '9') || c == '_') ++p;
52	    else break;
53	  }
54	  var = line.substr(0, p);
55	  while (p < n && (line[p] == ' ' || line[p] == '\t')) ++p;  // \s*
56	  if (p < n && line[p] == ':') ++p;                          // :?
57	  if (p >= n || line[p] != '=') return false;                // =
58	  ++p;
59	  body = line.substr(p);
60	  return true;
61	}
