21	// In the just-forked child: replace the image with argv (argv[0] resolved via
22	// PATH), or _exit(127) if exec fails. Never returns.
23	[[noreturn]] void exec_or_die(const std::vector<std::string>& argv) {
24	  std::vector<char*> cargv;
25	  cargv.reserve(argv.size() + 1);
26	  for (const std::string& a : argv) cargv.push_back(const_cast<char*>(a.c_str()));
27	  cargv.push_back(nullptr);
28	  execvp(cargv[0], cargv.data());
29	  _exit(127);  // exec failed
