42	// fork + (optional chdir) + (optional stdin from /dev/null) + exec.
43	// When `wait` is true (the default) waits for the child and returns its exit
44	// code, 128+signal if signalled, or -1 on failure. When `wait` is false
45	// returns the child pid immediately without waiting (caller owns the child).
46	// Backs run_inherit (build: stdin closed, chdir), exec_passthrough (run
47	// fast/cycle: stdin inherited, no chdir), and fork_background (no wait).
48	int spawn_inherit(const std::vector<std::string>& argv, const std::string& cwd,
49	                  bool stdin_from_devnull, bool wait = true) {
50	  if (argv.empty()) return -1;
51	
52	  pid_t pid = fork();
53	  if (pid < 0) return -1;
54	
55	  if (pid == 0) {  // child
56	    if (!cwd.empty() && chdir(cwd.c_str()) != 0) _exit(127);
57	    if (stdin_from_devnull) {
58	      int devnull = open("/dev/null", O_RDONLY);
59	      if (devnull >= 0) {
60	        dup2(devnull, STDIN_FILENO);
61	        if (devnull > 2) close(devnull);
62	      }
63	    }
64	    exec_or_die(argv);
65	  }
66	
67	  if (!wait) return static_cast<int>(pid);
68	  return wait_for_exit_code(pid);
69	}
