112	
113	  while (true) {
114	    long remaining = deadline - now_ms();
115	    if (remaining < 0) remaining = 0;
116	    struct pollfd pfd{rfd, POLLIN, 0};
117	    int pr = poll(&pfd, 1, static_cast<int>(remaining));
118	    if (pr < 0) {
119	      if (errno == EINTR) continue;
120	      break;
121	    }
122	    if (pr == 0) {  // timed out with no data ready
123	      kill(pid, SIGKILL);
124	      r.timed_out = true;
125	      break;
126	    }
127	    if (pfd.revents & (POLLIN | POLLHUP | POLLERR)) {
128	      ssize_t n = read(rfd, buf, sizeof(buf));
129	      if (n > 0) {
130	        r.out.append(buf, static_cast<size_t>(n));
131	      } else if (n == 0) {
132	        break;  // EOF: child closed stdout
133	      } else {
134	        if (errno == EINTR) continue;
135	        break;
136	      }
137	    }
138	    if (now_ms() >= deadline) {  // chatty child kept us past the deadline
139	      kill(pid, SIGKILL);
140	      r.timed_out = true;
141	      break;
142	    }
143	  }
