167	// Drain everything readable on `fd` into `buf`, delivering each completed
168	// '\n'-terminated line (newline stripped) to on_line. Returns false at EOF /
169	// error so the caller stops polling that stream.
170	bool pump_stream(int fd, int stream, std::string& buf,
171	                 const std::function<void(int, std::string_view)>& on_line) {
172	  char rb[4096];
173	  const ssize_t n = read(fd, rb, sizeof rb);
174	  if (n == 0) return false;          // EOF: child closed this stream
175	  if (n < 0) return errno == EINTR;  // transient -> keep; real error -> stop
176	  buf.append(rb, static_cast<size_t>(n));
177	  size_t nl;
178	  while ((nl = buf.find('\n')) != std::string::npos) {
179	    on_line(stream, std::string_view(buf.data(), nl));
180	    buf.erase(0, nl + 1);
181	  }
182	  return true;
183	}
