187	int run_line_filtered(
188	    const std::vector<std::string>& argv,
189	    const std::function<void(int, std::string_view)>& on_line) {
190	  if (argv.empty()) return -1;
191	
192	  int out_fds[2], err_fds[2];
193	  if (pipe(out_fds) != 0) return -1;
194	  if (pipe(err_fds) != 0) {
195	    close(out_fds[0]);
196	    close(out_fds[1]);
197	    return -1;
198	  }
199	
200	  pid_t pid = fork();
201	  if (pid < 0) {
202	    close(out_fds[0]);
203	    close(out_fds[1]);
204	    close(err_fds[0]);
205	    close(err_fds[1]);
206	    return -1;
207	  }
208	
209	  if (pid == 0) {  // child: stdout/stderr to the pipes, stdin inherited
210	    close(out_fds[0]);
211	    close(err_fds[0]);
212	    dup2(out_fds[1], STDOUT_FILENO);
213	    dup2(err_fds[1], STDERR_FILENO);
214	    if (out_fds[1] > 2) close(out_fds[1]);
215	    if (err_fds[1] > 2) close(err_fds[1]);
216	    exec_or_die(argv);
217	  }
218	
219	  // parent: poll both pipes, line-buffer each, until both hit EOF. No timeout --
220	  // matches exec_passthrough (a cycle run can be arbitrarily long). The stream id
221	  // is index+1 (0 -> stdout=1, 1 -> stderr=2); a closed stream's fd is set to -1,
222	  // which poll() ignores (revents 0).
223	  close(out_fds[1]);
224	  close(err_fds[1]);
225	  const int fd[2] = {out_fds[0], err_fds[0]};
226	  std::string buf[2];
227	  bool open_[2] = {true, true};
228	
229	  struct pollfd pfd[2] = {{fd[0], POLLIN, 0}, {fd[1], POLLIN, 0}};
230	  while (open_[0] || open_[1]) {
231	    for (int i = 0; i < 2; ++i) pfd[i].fd = open_[i] ? fd[i] : -1;
232	    if (poll(pfd, 2, -1) < 0) {
233	      if (errno == EINTR) continue;
234	      break;
235	    }
236	    for (int i = 0; i < 2; ++i)
237	      if (open_[i] && (pfd[i].revents & (POLLIN | POLLHUP | POLLERR)))
238	        if (!pump_stream(fd[i], i + 1, buf[i], on_line)) open_[i] = false;
239	  }
240	  // Flush any final line that arrived without a trailing newline.
241	  for (int i = 0; i < 2; ++i)
242	    if (!buf[i].empty()) on_line(i + 1, buf[i]);
243	
244	  close(fd[0]);
245	  close(fd[1]);
246	  return wait_for_exit_code(pid);
247	}
